const bundle = {"contentId":"c8bafa14-a1d2-47f5-8797-4d1d2d4c4a3d","sourceHashes":{"title":"37f549c6311f82dd1c6f06a7896adcb07263938269b25e0dfde7b8c883da31c6","description":"2de5638985058ec52c66d4897794079c5218b964e355b673e77858dd62e04cb7","content":"5ca798e0baab18ca0047f55f629c3bda979c1007d0cacb57d57e458f905eac33"},"references":[{"field":"title","index":0},{"field":"description","index":1},{"field":"content","start":145,"end":168,"index":2},{"field":"content","start":6656,"end":6668,"index":3},{"field":"content","start":6729,"end":6752,"index":2},{"field":"content","start":6792,"end":6992,"index":4},{"field":"content","start":7098,"end":7115,"index":5},{"field":"content","start":7180,"end":7203,"index":6},{"field":"content","start":7273,"end":7307,"index":7},{"field":"content","start":7372,"end":7411,"index":8},{"field":"content","start":7747,"end":7762,"index":9},{"field":"content","start":7790,"end":8110,"index":10},{"field":"content","start":8222,"end":8227,"index":11},{"field":"content","start":8263,"end":8279,"index":12},{"field":"content","start":8365,"end":8381,"index":13},{"field":"content","start":8417,"end":8479,"index":14},{"field":"content","start":8565,"end":8580,"index":15},{"field":"content","start":8616,"end":8682,"index":16},{"field":"content","start":8768,"end":8795,"index":17},{"field":"content","start":8831,"end":8900,"index":18},{"field":"content","start":9034,"end":9054,"index":19},{"field":"content","start":9082,"end":9421,"index":20},{"field":"content","start":9526,"end":9551,"index":21},{"field":"content","start":9579,"end":9836,"index":22},{"field":"content","start":9941,"end":9956,"index":23},{"field":"content","start":9984,"end":10208,"index":24},{"field":"content","start":10317,"end":10349,"index":25},{"field":"content","start":10382,"end":10471,"index":26},{"field":"content","start":10491,"end":10634,"index":27},{"field":"content","start":10654,"end":10733,"index":28},{"field":"content","start":10753,"end":10848,"index":29},{"field":"content","start":10868,"end":10967,"index":30},{"field":"content","start":11078,"end":11092,"index":31},{"field":"content","start":11120,"end":11411,"index":32},{"field":"content","start":11516,"end":11527,"index":33},{"field":"content","start":11555,"end":11872,"index":34},{"field":"content","start":11995,"end":12015,"index":35},{"field":"content","start":12043,"end":12353,"index":36}],"translations":{"it":["Il fondatore: Dr. Eymen NAMAZCI","Breve presentazione del fondatore, del suo percorso professionale, della sua visione e della credibilità istituzionale.","Il Dr. Eymen NAMAZCI","G1 — Fondatore","Questa lezione presenta il fondatore di Find And Study, il suo percorso accademico e professionale e la sua visione di sviluppo istituzionale, che unisce istruzione, società civile e organizzazione operativa.","Fondatore e amministratore delegato","Istruzione internazionale","Società civile e affari pubblici","Leadership accademica e istituzionale","Profilo del fondatore","Il Dr. Eymen NAMAZCI è il fondatore di Find And Study, un’organizzazione che promuove all’estero le università della Türkiye e orienta gli studenti internazionali verso le opportunità di studio nel Paese. È noto per riunire istruzione, coordinamento istituzionale e costruzione di partnership durature in una struttura professionale.","Nascita","Nato a Istanbul","Ambiti di leadership","Istruzione, istituzioni, partnership e sistemi sostenibili","Profilo attuale","Fondatore, dirigente, esponente della società civile e professionista accademico","Perché è importante per l’Academy","Spiega la cultura istituzionale alla base del modello Find And Study","Formazione","Ha conseguito la laurea in Amministrazione pubblica presso l’Università di Sakarya nel 2007. Nel 2013 ha completato con successo il master con tesi in Amministrazioni locali e decentramento presso l’Università di Marmara. Nel 2023 ha completato il dottorato in Amministrazione pubblica e Scienze politiche presso l’Università di Istanbul.","Gli inizi della carriera professionale","Ha iniziato la sua vita professionale come insegnante presso le Murat Educational Institutions nel 2006, proseguendo in questo ruolo fino al 2018. Nello stesso periodo ha sviluppato un profilo che univa la pratica educativa a responsabilità organizzative e di leadership.","Carriera accademica","Nel 2013 ha iniziato a lavorare come docente presso l’Università Istanbul Ayvansaray, dove è rimasto fino all’agosto 2019. Questo ruolo ha rafforzato il suo legame con l’istruzione superiore, l’amministrazione accademica e la cultura istituzionale.","Società civile e incarichi pubblici","È stato segretario generale del Beyoğlu Businessmen Group (BIG) dal 2016 al 2019.","Il 10 ottobre 2017 è stato eletto segretario generale del comitato esecutivo del Consiglio cittadino di Beyoğlu, incarico che ha lasciato dopo le elezioni locali del 2019.","È stato direttore fondatore di Akademi Beyoğlu, avviata nel 2019.","È stato eletto membro del consiglio direttivo di Medeniyet Derneği durante l’assemblea generale del 21 maggio 2018.","Ricopre inoltre il ruolo di direttore della Fondazione per la ricerca, la solidarietà e l’istruzione (ARDEV).","Find And Study","È il fondatore di Find And Study, che promuove all’estero le università della Türkiye e supporta l’inserimento degli studenti internazionali nell’istruzione superiore turca. Questo ruolo esprime una missione fondata sulla promozione educativa, l’internazionalizzazione e la cooperazione strutturata.","Il ruolo in MÜMDER","Durante l’assemblea generale del giugno 2021 è stato eletto membro del consiglio direttivo di MÜMDER, l’Associazione dei laureati e dei membri dell’Università di Marmara, e responsabile dell’unità per i rapporti con le organizzazioni della società civile. Questa responsabilità evidenzia il suo ruolo attivo nei rapporti con gli ex studenti e nelle reti della società civile.","Sintesi professionale","Il Dr. Eymen NAMAZCI ha costruito la propria carriera nell’istruzione, nel mondo accademico, nella società civile e nella leadership istituzionale. Il suo profilo unisce iniziativa imprenditoriale e impegno duraturo per lo sviluppo educativo, la partecipazione pubblica e l’organizzazione delle istituzioni."],"pt":["Sobre o fundador: Dr. Eymen NAMAZCI","Breve apresentação do fundador, do seu percurso profissional, da sua visão e da credibilidade institucional.","Sobre o Dr. Eymen NAMAZCI","G1 — Fundador","Esta lição apresenta o fundador da Find And Study, o seu percurso académico e profissional e a sua visão de desenvolvimento institucional, que reúne educação, sociedade civil e organização operacional.","Fundador e diretor executivo","Educação internacional","Sociedade civil e assuntos públicos","Liderança académica e institucional","Perfil do fundador","O Dr. Eymen NAMAZCI é o fundador da Find And Study, uma organização que promove no estrangeiro as universidades da Türkiye e orienta estudantes internacionais para oportunidades de estudo no país. É conhecido por reunir educação, coordenação institucional e construção de parcerias duradouras numa estrutura profissional.","Nascimento","Nasceu em Istambul","Áreas de liderança","Educação, instituições, parcerias e sistemas sustentáveis","Perfil atual","Fundador, dirigente, interveniente na sociedade civil e profissional académico","Porque é importante na Academy","Explica a cultura institucional por detrás do modelo Find And Study","Formação académica","Concluiu a licenciatura em Administração Pública na Universidade de Sakarya em 2007. Em 2013, concluiu com sucesso o mestrado com dissertação em Administrações Locais e Descentralização na Universidade de Marmara. Em 2023, concluiu o doutoramento em Administração Pública e Ciência Política na Universidade de Istambul.","Início do percurso profissional","Iniciou a sua vida profissional como professor nas Murat Educational Institutions em 2006 e manteve essa função até 2018. No mesmo período, desenvolveu um perfil que combinava prática educativa com responsabilidade organizacional e liderança.","Carreira académica","Em 2013, começou a trabalhar como docente na Universidade Istanbul Ayvansaray, onde permaneceu até agosto de 2019. Esta função reforçou a sua ligação ao ensino superior, à administração académica e à cultura institucional.","Sociedade civil e funções públicas","Foi secretário-geral do Beyoğlu Businessmen Group (BIG) entre 2016 e 2019.","Foi eleito secretário-geral da Comissão Executiva do Conselho da Cidade de Beyoğlu em 10 de outubro de 2017 e deixou a função após as eleições locais de 2019.","Foi diretor fundador da Akademi Beyoğlu, lançada em 2019.","Foi eleito membro da direção da Medeniyet Derneği na assembleia geral de 21 de maio de 2018.","Exerce também funções de diretor da Fundação de Investigação, Solidariedade e Educação (ARDEV).","Find And Study","É o fundador da Find And Study, que promove as universidades da Türkiye no estrangeiro e apoia a colocação de estudantes internacionais no ensino superior turco. Esta função reflete uma missão assente na promoção da educação, na internacionalização e na cooperação estruturada.","Função na MÜMDER","Na assembleia geral de junho de 2021, foi eleito membro da direção da MÜMDER, a Associação de Diplomados e Membros da Universidade de Marmara, e responsável pela Unidade de Relações com Organizações da Sociedade Civil. Esta responsabilidade destaca o seu papel ativo nas relações com antigos alunos e nas redes da sociedade civil.","Síntese profissional","O Dr. Eymen NAMAZCI construiu a sua carreira na educação, no meio académico, na sociedade civil e na liderança institucional. O seu perfil reúne iniciativa empresarial e compromisso duradouro com o desenvolvimento educativo, a participação pública e a organização institucional."],"uk":["Про засновника: Dr. Eymen NAMAZCI","Коротке знайомство із засновником, його професійним шляхом, баченням і надійністю організації.","Про Dr. Eymen NAMAZCI","G1 — Засновник","Цей урок знайомить із засновником Find And Study, його академічним і професійним шляхом та баченням розвитку інституцій, що поєднує освіту, громадянське суспільство й операційну діяльність.","Засновник і генеральний директор","Міжнародна освіта","Громадянське суспільство та суспільні справи","Академічне та інституційне лідерство","Профіль засновника","Dr. Eymen NAMAZCI — засновник Find And Study, організації, яка популяризує університети Туреччини за кордоном і допомагає іноземним студентам знайти можливості навчання в Туреччині. Він відомий поєднанням освіти, інституційної координації та побудови довгострокових партнерств у професійній структурі.","Народження","Народився в Стамбулі","Напрями лідерства","Освіта, інституції, партнерства та сталі системи","Нинішній профіль","Засновник, керівник, громадський діяч і фахівець академічної сфери","Чому це важливо в Academy","Пояснює інституційний підхід, що лежить в основі моделі Find And Study","Освіта","У 2007 році він здобув ступінь бакалавра з державного управління в Університеті Сакар’я. У 2013 році успішно закінчив магістерську програму з дисертацією за напрямом місцевого управління та децентралізації в Університеті Мармара. У 2023 році завершив докторантуру з державного управління та політичних наук у Стамбульському університеті.","Початок професійної кар’єри","У 2006 році він розпочав професійну діяльність учителем у Murat Educational Institutions і працював на цій посаді до 2018 року. У цей самий період він поєднував освітню практику з організаційною відповідальністю та керівництвом.","Академічна кар’єра","У 2013 році він почав працювати викладачем в Університеті Istanbul Ayvansaray і залишався там до серпня 2019 року. Ця робота зміцнила його зв’язок із вищою освітою, академічним адмініструванням та інституційною культурою.","Громадянське суспільство та суспільні ролі","У 2016–2019 роках обіймав посаду генерального секретаря Beyoğlu Businessmen Group (BIG).","10 жовтня 2017 року його було обрано генеральним секретарем виконавчого комітету Міської ради Бейоглу; він залишив цю посаду після місцевих виборів 2019 року.","Був директором-засновником Akademi Beyoğlu, започаткованої у 2019 році.","На загальних зборах 21 травня 2018 року його було обрано членом правління Medeniyet Derneği.","Також обіймає посаду директора Фонду досліджень, солідарності та освіти (ARDEV).","Find And Study","Він є засновником Find And Study, яка популяризує турецькі університети за кордоном і підтримує вступ іноземних студентів до закладів вищої освіти Туреччини. Ця роль відображає місію, засновану на просуванні освіти, інтернаціоналізації та структурованій співпраці.","Роль у MÜMDER","На загальних зборах у червні 2021 року його було обрано членом правління MÜMDER — Асоціації випускників і членів Університету Мармара — та керівником підрозділу зв’язків з організаціями громадянського суспільства. Ця відповідальність підкреслює його активну роль у зв’язках із випускниками та громадських мережах.","Професійний підсумок","Dr. Eymen NAMAZCI побудував кар’єру в освіті, академічній сфері, громадянському суспільстві та інституційному керівництві. Його профіль поєднує підприємницьку ініціативу з довгостроковою відданістю розвитку освіти, громадській участі та організаційній структурі."],"vi":["Về nhà sáng lập: Dr. Eymen NAMAZCI","Giới thiệu ngắn về nhà sáng lập, kinh nghiệm chuyên môn, tầm nhìn và uy tín tổ chức.","Về Dr. Eymen NAMAZCI","G1 — Nhà sáng lập","Bài học này giới thiệu nhà sáng lập Find And Study, nền tảng học thuật và chuyên môn của ông, cùng tầm nhìn xây dựng tổ chức kết hợp giáo dục, xã hội dân sự và phát triển vận hành.","Nhà sáng lập và Tổng giám đốc","Giáo dục quốc tế","Xã hội dân sự và công vụ","Lãnh đạo học thuật và tổ chức","Hồ sơ nhà sáng lập","Dr. Eymen NAMAZCI là nhà sáng lập Find And Study, tổ chức quảng bá các trường đại học Türkiye ra nước ngoài và hướng dẫn sinh viên quốc tế tiếp cận cơ hội học tập tại Türkiye. Ông được biết đến với việc kết hợp giáo dục, điều phối tổ chức và xây dựng quan hệ đối tác lâu dài trong một cơ cấu chuyên nghiệp.","Nơi sinh","Sinh tại Istanbul","Trọng tâm lãnh đạo","Giáo dục, tổ chức, quan hệ đối tác và hệ thống bền vững","Vai trò hiện nay","Nhà sáng lập, nhà điều hành, người hoạt động xã hội dân sự và chuyên gia học thuật","Ý nghĩa đối với Academy","Giải thích tư duy tổ chức đằng sau mô hình Find And Study","Nền tảng giáo dục","Ông hoàn thành bằng cử nhân Quản lý công tại Đại học Sakarya năm 2007. Năm 2013, ông tốt nghiệp chương trình thạc sĩ có luận văn về Chính quyền địa phương và Phân cấp tại Đại học Marmara. Đến năm 2023, ông hoàn thành chương trình tiến sĩ về Quản lý công và Khoa học chính trị tại Đại học Istanbul.","Giai đoạn đầu sự nghiệp","Ông bắt đầu sự nghiệp với vai trò giáo viên tại Murat Educational Institutions năm 2006 và tiếp tục công việc này đến năm 2018. Trong cùng thời kỳ, ông phát triển năng lực kết hợp thực hành giáo dục với trách nhiệm tổ chức và lãnh đạo.","Sự nghiệp học thuật","Năm 2013, ông bắt đầu làm giảng viên tại Đại học Istanbul Ayvansaray và làm việc tại đây đến tháng 8 năm 2019. Vai trò này củng cố mối liên hệ của ông với giáo dục đại học, quản trị học thuật và văn hóa tổ chức.","Vai trò trong xã hội dân sự và lĩnh vực công","Ông giữ chức Tổng thư ký Beyoğlu Businessmen Group (BIG) từ năm 2016 đến năm 2019.","Ngày 10 tháng 10 năm 2017, ông được bầu làm Tổng thư ký Ban điều hành Hội đồng thành phố Beyoğlu và rời vị trí này sau cuộc bầu cử địa phương năm 2019.","Ông là giám đốc sáng lập Akademi Beyoğlu, được triển khai năm 2019.","Ông được bầu làm thành viên Ban quản trị Medeniyet Derneği tại Đại hội đồng ngày 21 tháng 5 năm 2018.","Ông cũng đảm nhiệm vai trò giám đốc Quỹ Nghiên cứu, Đoàn kết và Giáo dục (ARDEV).","Find And Study","Ông là nhà sáng lập Find And Study, tổ chức quảng bá các trường đại học Türkiye ở nước ngoài và hỗ trợ sinh viên quốc tế vào học trong hệ thống giáo dục đại học Thổ Nhĩ Kỳ. Vai trò này thể hiện sứ mệnh dựa trên quảng bá giáo dục, quốc tế hóa và hợp tác có tổ chức.","Vai trò tại MÜMDER","Tại Đại hội đồng tháng 6 năm 2021, ông được bầu làm thành viên Ban quản trị MÜMDER, Hiệp hội Cựu sinh viên và Thành viên Đại học Marmara, đồng thời là Trưởng đơn vị Quan hệ với các tổ chức xã hội dân sự. Trách nhiệm này thể hiện vai trò tích cực của ông trong quan hệ cựu sinh viên và kết nối xã hội dân sự.","Tóm tắt chuyên môn","Dr. Eymen NAMAZCI xây dựng sự nghiệp trong giáo dục, học thuật, xã hội dân sự và lãnh đạo tổ chức. Hồ sơ của ông kết hợp tinh thần khởi nghiệp với cam kết lâu dài đối với phát triển giáo dục, sự tham gia vào hoạt động công và cơ cấu tổ chức."],"tk":["Esaslandyryjy barada: Dr. Eymen NAMAZCI","Esaslandyryjy, onuň hünär tejribesi, garaýşy we guramanyň ynamdarlygy barada gysgaça tanyşdyryş.","Dr. Eymen NAMAZCI barada","G1 — Esaslandyryjy","Bu sapak Find And Study-yň esaslandyryjysy, onuň akademiki we hünär geçmişi hem-de bilimi, raýat jemgyýetini we iş dolandyryşyny birleşdirýän guramaçylyk ösüş garaýşy bilen tanyşdyrýar.","Esaslandyryjy we baş ýerine ýetiriji direktor","Halkara bilim","Raýat jemgyýeti we jemgyýetçilik işleri","Akademiki we guramaçylyk ýolbaşçylygy","Esaslandyryjynyň profili","Dr. Eymen NAMAZCI Türkiýedäki uniwersitetleri daşary ýurtlarda tanatmak we halkara talyplary Türkiýedäki okuw mümkinçiliklerine ugrukdyrmak üçin işleýän Find And Study guramasynyň esaslandyryjysydyr. Ol bilimi, edaralaryň arasyndaky utgaşdyrmany we uzak möhletli hyzmatdaşlygy hünär gurluşynyň çäginde birleşdirmegi bilen tanalýar.","Doglan ýeri","Stambulda doguldy","Ýolbaşçylyk ugurlary","Bilim, edaralar, hyzmatdaşlyk we durnukly ulgamlar","Häzirki profili","Esaslandyryjy, ýolbaşçy, raýat jemgyýetiniň wekili we akademiki hünärmen","Munuň Academy üçin ähmiýeti","Find And Study modeliniň aňyrsyndaky guramaçylyk pikirlenmesini düşündirýär","Bilimi","2007-nji ýylda Sakarya uniwersitetinde döwlet dolandyryşy boýunça bakalawr derejesini tamamlady. 2013-nji ýylda Marmara uniwersitetinde ýerli dolandyryş we merkezden daşlaşdyrma boýunça dissertasiýaly magistrlik maksatnamasyny üstünlikli gutardy. 2023-nji ýylda Stambul uniwersitetinde döwlet dolandyryşy we syýasat ylymlary boýunça doktorlyk okuwyny tamamlady.","Ilkinji hünär işi","Hünär durmuşyna 2006-njy ýylda Murat Educational Institutions-da mugallym bolup başlady we bu wezipede 2018-nji ýyla çenli işledi. Şol döwürde bilim tejribesini guramaçylyk jogapkärçiligi we ýolbaşçylyk bilen birleşdirýän hünär ugruny ösdürdi.","Akademiki işi","2013-nji ýylda Istanbul Ayvansaray uniwersitetinde lektor bolup işe başlady we 2019-njy ýylyň awgustyna çenli şol ýerde işledi. Bu wezipe onuň ýokary bilim, akademiki dolandyryş we guramaçylyk medeniýeti bilen baglanyşygyny güýçlendirdi.","Raýat jemgyýeti we jemgyýetçilik wezipeleri","2016–2019-njy ýyllarda Beyoğlu Businessmen Group-yň (BIG) baş sekretary bolup işledi.","2017-nji ýylyň 10-njy oktýabrynda Beýogly şäher geňeşiniň ýerine ýetiriji geňeşiniň baş sekretary saýlandy we 2019-njy ýylyň ýerli saýlawlaryndan soň bu wezipeden aýryldy.","2019-njy ýylda işe girizilen Akademi Beyoğlu-nyň esaslandyryjy direktory bolup işledi.","2018-nji ýylyň 21-nji maýynda geçirilen umumy ýygnakda Medeniyet Derneği-niň dolandyryş geňeşiniň agzasy saýlandy.","Şeýle hem Ylmy-barlag, raýdaşlyk we bilim gaznasynyň (ARDEV) direktory bolup işleýär.","Find And Study","Ol Türkiýedäki uniwersitetleri daşary ýurtlarda tanadýan we halkara talyplaryň türk ýokary bilim ulgamyna ýerleşdirilmegine goldaw berýän Find And Study-yň esaslandyryjysydyr. Bu wezipe bilimi tanatmaga, halkaralaşmaga we tertipli hyzmatdaşlyga esaslanýan maksady görkezýär.","MÜMDER-däki wezipesi","2021-nji ýylyň iýun aýynda geçirilen umumy ýygnakda MÜMDER-iň — Marmara uniwersitetiniň uçurymlary we agzalary birleşiginiň — dolandyryş geňeşiniň agzasy hem-de raýat jemgyýeti guramalary bilen gatnaşyklar bölüminiň ýolbaşçysy saýlandy. Bu jogapkärçilik onuň uçurymlar bilen gatnaşyklarda we raýat jemgyýetiniň hyzmatdaşlyk ulgamynda işjeň ornuny görkezýär.","Hünär jemlemesi","Dr. Eymen NAMAZCI öz hünär ýoluny bilim, akademiki iş, raýat jemgyýeti we guramaçylyk ýolbaşçylygy ugurlarynda gurdy. Onuň profili telekeçilik başlangyjyny bilimi ösdürmäge, jemgyýetçilik gatnaşygyna we guramaçylyk gurluşyna bolan uzak möhletli ygrarlylyk bilen birleşdirýär."],"uz":["Asoschi haqida: Dr. Eymen NAMAZCI","Asoschi, uning kasbiy tajribasi, qarashlari va tashkilotning ishonchliligi haqida qisqacha ma’lumot.","Dr. Eymen NAMAZCI haqida","G1 — Asoschi","Ushbu dars Find And Study asoschisi, uning akademik va kasbiy yo‘li hamda ta’lim, fuqarolik jamiyati va faoliyatni rivojlantirishni birlashtiruvchi tashkilot qurish qarashlari bilan tanishtiradi.","Asoschi va bosh ijrochi direktor","Xalqaro ta’lim","Fuqarolik jamiyati va jamoat ishlari","Akademik va institutsional yetakchilik","Asoschi profili","Dr. Eymen NAMAZCI Turkiya universitetlarini xorijda targ‘ib qilish va xalqaro talabalarni Turkiyadagi ta’lim imkoniyatlariga yo‘naltirish bilan shug‘ullanuvchi Find And Study tashkilotining asoschisidir. U ta’lim, tashkilotlararo muvofiqlashtirish va uzoq muddatli hamkorlikni professional tuzilma doirasida birlashtirishi bilan tanilgan.","Tug‘ilgan joyi","Istanbulda tug‘ilgan","Yetakchilik yo‘nalishlari","Ta’lim, tashkilotlar, hamkorlik va barqaror tizimlar","Hozirgi profili","Asoschi, rahbar, fuqarolik jamiyati vakili va akademik mutaxassis","Bu Academy uchun nega muhim","Find And Study modeli asosidagi institutsional fikrlashni tushuntiradi","Ta’limi","2007-yilda Sakarya universitetida davlat boshqaruvi yo‘nalishi bo‘yicha bakalavr darajasini olgan. 2013-yilda Marmara universitetida mahalliy boshqaruv va markazsizlashtirish bo‘yicha dissertatsiyali magistratura dasturini muvaffaqiyatli tamomlagan. 2023-yilda Istanbul universitetida davlat boshqaruvi va siyosiy fanlar bo‘yicha doktoranturani tugatgan.","Kasbiy faoliyatning boshlanishi","Kasbiy faoliyatini 2006-yilda Murat Educational Institutions’da o‘qituvchi sifatida boshlagan va bu lavozimda 2018-yilgacha ishlagan. Shu davrda u ta’lim amaliyotini tashkiliy mas’uliyat va rahbarlik bilan birlashtirgan kasbiy yo‘nalishni rivojlantirgan.","Akademik faoliyati","2013-yilda Istanbul Ayvansaray universitetida o‘qituvchi bo‘lib ishlay boshlagan va 2019-yil avgustigacha shu yerda faoliyat yuritgan. Bu vazifa uning oliy ta’lim, akademik boshqaruv va institutsional madaniyat bilan aloqasini mustahkamlagan.","Fuqarolik jamiyati va jamoat vazifalari","2016–2019-yillarda Beyoğlu Businessmen Group (BIG) bosh kotibi bo‘lib ishlagan.","2017-yil 10-oktabrda Beyog‘lu shahar kengashi ijroiya hay’ati bosh kotibi etib saylangan va 2019-yilgi mahalliy saylovlardan keyin bu vazifani tark etgan.","2019-yilda ishga tushirilgan Akademi Beyoğlu’ning asoschi direktori bo‘lib ishlagan.","2018-yil 21-maydagi umumiy yig‘ilishda Medeniyet Derneği boshqaruv kengashi a’zosi etib saylangan.","Shuningdek, Tadqiqot, birdamlik va ta’lim jamg‘armasi (ARDEV) direktori sifatida faoliyat yuritadi.","Find And Study","U Turkiya universitetlarini xorijda targ‘ib qiladigan va xalqaro talabalarni Turkiya oliy ta’lim tizimiga joylashtirishga ko‘maklashadigan Find And Study asoschisidir. Bu vazifa ta’limni targ‘ib qilish, xalqaro aloqalarni kengaytirish va tizimli hamkorlikka asoslangan maqsadni aks ettiradi.","MÜMDER’dagi vazifasi","2021-yil iyundagi umumiy yig‘ilishda MÜMDER — Marmara universiteti bitiruvchilari va a’zolari uyushmasi — boshqaruv kengashi a’zosi hamda fuqarolik jamiyati tashkilotlari bilan aloqalar bo‘limi rahbari etib saylangan. Bu mas’uliyat uning bitiruvchilar bilan aloqalar va fuqarolik jamiyati tarmoqlaridagi faol rolini ko‘rsatadi.","Kasbiy xulosa","Dr. Eymen NAMAZCI o‘z faoliyatini ta’lim, akademik soha, fuqarolik jamiyati va institutsional rahbarlik yo‘nalishlarida rivojlantirgan. Uning profili tadbirkorlik tashabbusini ta’lim rivoji, jamoatchilik ishtiroki va tashkiliy tuzilmaga uzoq muddatli sadoqat bilan birlashtiradi."],"tg":["Дар бораи асосгузор: Dr. Eymen NAMAZCI","Шиносоии кӯтоҳ бо асосгузор, таҷрибаи касбӣ, дидгоҳ ва эътимоднокии ташкилот.","Дар бораи Dr. Eymen NAMAZCI","G1 — Асосгузор","Ин дарс асосгузори Find And Study, роҳи илмӣ ва касбии ӯ ва дидгоҳи бунёди ташкилотро муаррифӣ мекунад, ки маориф, ҷомеаи шаҳрвандӣ ва рушди фаъолияти амалиро ба ҳам мепайвандад.","Асосгузор ва директори иҷроия","Таҳсилоти байналмилалӣ","Ҷомеаи шаҳрвандӣ ва корҳои ҷамъиятӣ","Роҳбарии илмӣ ва институтсионалӣ","Маълумоти асосгузор","Dr. Eymen NAMAZCI асосгузори Find And Study аст. Ин ташкилот донишгоҳҳои Туркияро дар хориҷ муаррифӣ мекунад ва донишҷӯёни байналмилалиро ба имкониятҳои таҳсил дар Туркия роҳнамоӣ менамояд. Ӯ бо пайвастани маориф, ҳамоҳангсозии байни муассисаҳо ва бунёди шарикиҳои дарозмуддат дар як сохтори касбӣ шинохта шудааст.","Зодгоҳ","Дар Истанбул таваллуд шудааст","Самтҳои роҳбарӣ","Маориф, муассисаҳо, шарикӣ ва низомҳои устувор","Нақши кунунӣ","Асосгузор, роҳбар, фаъоли ҷомеаи шаҳрвандӣ ва мутахассиси илмӣ","Аҳамияти ин дар Academy","Тафаккури институтсионалии паси модели Find And Study-ро шарҳ медиҳад","Маълумоти таҳсилӣ","Соли 2007 дараҷаи бакалавриро аз рӯйи ихтисоси идоракунии давлатӣ дар Донишгоҳи Сакария хатм кардааст. Соли 2013 барномаи магистрии дорои рисоларо дар соҳаи идоракунии маҳаллӣ ва ғайримарказикунонӣ дар Донишгоҳи Мармара бомуваффақият анҷом додааст. Соли 2023 докторантураро дар соҳаи идоракунии давлатӣ ва илмҳои сиёсӣ дар Донишгоҳи Истанбул хатм кардааст.","Оғози фаъолияти касбӣ","Фаъолияти касбиашро соли 2006 ҳамчун омӯзгор дар Murat Educational Institutions оғоз карда, то соли 2018 дар ин вазифа кор кардааст. Дар ҳамин давра таҷрибаи таълимиро бо масъулияти ташкилӣ ва роҳбарӣ якҷо инкишоф додааст.","Фаъолияти илмӣ","Соли 2013 ба ҳайси омӯзгор дар Донишгоҳи Istanbul Ayvansaray ба кор оғоз карда, то августи соли 2019 дар он ҷо фаъолият намудааст. Ин вазифа робитаи ӯро бо таҳсилоти олӣ, идоракунии академӣ ва фарҳанги ташкилӣ мустаҳкам кардааст.","Ҷомеаи шаҳрвандӣ ва вазифаҳои ҷамъиятӣ","Дар солҳои 2016–2019 котиби генералии Beyoğlu Businessmen Group (BIG) будааст.","10 октябри соли 2017 котиби генералии ҳайати иҷроияи Шӯрои шаҳрии Бейоғлу интихоб шуда, пас аз интихоботи маҳаллии соли 2019 ин вазифаро тарк кардааст.","Директори асосгузори Akademi Beyoğlu будааст, ки соли 2019 оғоз шуд.","Дар маҷлиси умумии 21 майи соли 2018 узви ҳайати роҳбарии Medeniyet Derneği интихоб шудааст.","Ҳамчунин директори Бунёди таҳқиқот, ҳамбастагӣ ва маориф (ARDEV) мебошад.","Find And Study","Ӯ асосгузори Find And Study аст, ки донишгоҳҳои Туркияро дар хориҷ муаррифӣ мекунад ва ба ҷойгиршавии донишҷӯёни байналмилалӣ дар таҳсилоти олии Туркия кумак мерасонад. Ин нақш рисолатеро инъикос мекунад, ки бар муаррифии маориф, байналмилалисозӣ ва ҳамкории муназзам асос ёфтааст.","Нақш дар MÜMDER","Дар маҷлиси умумии моҳи июни соли 2021 узви ҳайати роҳбарии MÜMDER — Ассотсиатсияи хатмкунандагон ва аъзои Донишгоҳи Мармара — ва роҳбари бахши муносибатҳо бо ташкилотҳои ҷомеаи шаҳрвандӣ интихоб шудааст. Ин масъулият нақши фаъоли ӯро дар робита бо хатмкунандагон ва шабакаҳои ҷомеаи шаҳрвандӣ нишон медиҳад.","Хулосаи касбӣ","Dr. Eymen NAMAZCI фаъолияти худро дар маориф, соҳаи илмӣ, ҷомеаи шаҳрвандӣ ва роҳбарии институтсионалӣ бунёд кардааст. Профили ӯ ташаббуси соҳибкориро бо садоқати дарозмуддат ба рушди маориф, иштироки ҷамъиятӣ ва сохтори ташкилӣ якҷо мекунад."],"hi":["संस्थापक के बारे में: Dr. Eymen NAMAZCI","संस्थापक, उनकी पेशेवर पृष्ठभूमि, दृष्टि और संस्थागत विश्वसनीयता का संक्षिप्त परिचय।","Dr. Eymen NAMAZCI के बारे में","G1 — संस्थापक","यह पाठ Find And Study के संस्थापक, उनकी शैक्षणिक और पेशेवर पृष्ठभूमि तथा शिक्षा, नागरिक समाज और कार्य संचालन के विकास को जोड़ने वाली संस्था निर्माण की उनकी दृष्टि का परिचय देता है।","संस्थापक और मुख्य कार्यकारी अधिकारी","अंतरराष्ट्रीय शिक्षा","नागरिक समाज और सार्वजनिक कार्य","शैक्षणिक और संस्थागत नेतृत्व","संस्थापक का परिचय","Dr. Eymen NAMAZCI, Find And Study के संस्थापक हैं। यह संस्था तुर्किये के विश्वविद्यालयों को विदेशों में बढ़ावा देती है और अंतरराष्ट्रीय छात्रों को तुर्किये में अध्ययन के अवसरों की जानकारी देती है। वे शिक्षा, संस्थागत समन्वय और दीर्घकालिक साझेदारी निर्माण को एक पेशेवर ढाँचे में जोड़ने के लिए जाने जाते हैं।","जन्म","इस्तांबुल में जन्म","नेतृत्व के प्रमुख क्षेत्र","शिक्षा, संस्थाएँ, साझेदारियाँ और टिकाऊ प्रणालियाँ","वर्तमान परिचय","संस्थापक, कार्यकारी, नागरिक समाज में सक्रिय व्यक्ति और शैक्षणिक पेशेवर","Academy में इसका महत्व","यह Find And Study मॉडल के पीछे की संस्थागत सोच समझाता है","शैक्षणिक पृष्ठभूमि","उन्होंने 2007 में साकार्या विश्वविद्यालय से लोक प्रशासन में स्नातक की पढ़ाई पूरी की। 2013 में उन्होंने मारमारा विश्वविद्यालय से स्थानीय प्रशासन और विकेंद्रीकरण में शोधप्रबंध आधारित स्नातकोत्तर कार्यक्रम सफलतापूर्वक पूरा किया। 2023 में उन्होंने इस्तांबुल विश्वविद्यालय से लोक प्रशासन और राजनीति विज्ञान में पीएचडी पूरी की।","पेशेवर जीवन की शुरुआत","उन्होंने 2006 में Murat Educational Institutions में शिक्षक के रूप में अपना पेशेवर जीवन शुरू किया और 2018 तक इस भूमिका में रहे। इसी अवधि में उन्होंने शैक्षणिक अभ्यास को संगठनात्मक जिम्मेदारी और नेतृत्व के साथ जोड़ने वाला पेशेवर परिचय विकसित किया।","शैक्षणिक करियर","2013 में उन्होंने Istanbul Ayvansaray विश्वविद्यालय में व्याख्याता के रूप में काम शुरू किया और अगस्त 2019 तक वहाँ रहे। इस भूमिका ने उच्च शिक्षा, शैक्षणिक प्रशासन और संस्थागत संस्कृति से उनका जुड़ाव मजबूत किया।","नागरिक समाज और सार्वजनिक भूमिकाएँ","2016 से 2019 के बीच Beyoğlu Businessmen Group (BIG) के महासचिव रहे।","10 अक्टूबर 2017 को वे बेयोग्लू नगर परिषद के कार्यकारी बोर्ड के महासचिव चुने गए और 2019 के स्थानीय चुनावों के बाद यह भूमिका छोड़ दी।","2019 में शुरू हुई Akademi Beyoğlu के संस्थापक निदेशक रहे।","21 मई 2018 की आम सभा में Medeniyet Derneği के बोर्ड सदस्य चुने गए।","वे अनुसंधान, एकजुटता और शिक्षा फाउंडेशन (ARDEV) के निदेशक के रूप में भी कार्यरत हैं।","Find And Study","वे Find And Study के संस्थापक हैं, जो तुर्किये के विश्वविद्यालयों को विदेशों में बढ़ावा देती है और अंतरराष्ट्रीय छात्रों को तुर्की उच्च शिक्षा संस्थानों में प्रवेश दिलाने में सहायता करती है। यह भूमिका शिक्षा के प्रचार, अंतरराष्ट्रीयकरण और सुव्यवस्थित सहयोग पर आधारित उद्देश्य को दर्शाती है।","MÜMDER में भूमिका","जून 2021 की आम सभा में वे MÜMDER, यानी मारमारा विश्वविद्यालय के स्नातकों और सदस्यों के संघ, के बोर्ड सदस्य और नागरिक समाज संगठनों से संबंध इकाई के प्रमुख चुने गए। यह जिम्मेदारी पूर्व छात्रों से संबंध और नागरिक समाज के नेटवर्क में उनकी सक्रिय भूमिका को रेखांकित करती है।","पेशेवर सारांश","Dr. Eymen NAMAZCI ने शिक्षा, अकादमिक क्षेत्र, नागरिक समाज और संस्थागत नेतृत्व में अपना करियर बनाया है। उनका परिचय उद्यमशील पहल को शैक्षणिक विकास, सार्वजनिक भागीदारी और संगठनात्मक संरचना के प्रति दीर्घकालिक प्रतिबद्धता से जोड़ता है।"],"ur":["بانی کے بارے میں: Dr. Eymen NAMAZCI","بانی، ان کے پیشہ ورانہ پس منظر، وژن اور ادارہ جاتی ساکھ کا مختصر تعارف۔","Dr. Eymen NAMAZCI کے بارے میں","G1 — بانی","یہ سبق Find And Study کے بانی، ان کے علمی و پیشہ ورانہ پس منظر اور ادارہ سازی کے اس وژن کا تعارف کراتا ہے جو تعلیم، سول سوسائٹی اور عملی ترقی کو یکجا کرتا ہے۔","بانی اور چیف ایگزیکٹو آفیسر","بین الاقوامی تعلیم","سول سوسائٹی اور عوامی امور","علمی اور ادارہ جاتی قیادت","بانی کا تعارف","Dr. Eymen NAMAZCI، Find And Study کے بانی ہیں۔ یہ ادارہ ترکیہ کی جامعات کو بیرون ملک متعارف کرانے اور بین الاقوامی طلبہ کو ترکیہ میں تعلیمی مواقع کی طرف رہنمائی دینے کے لیے کام کرتا ہے۔ وہ تعلیم، ادارہ جاتی ہم آہنگی اور طویل مدتی شراکت داریوں کی تعمیر کو ایک پیشہ ورانہ ڈھانچے میں یکجا کرنے کے لیے معروف ہیں۔","پیدائش","استنبول میں پیدا ہوئے","قیادت کے اہم شعبے","تعلیم، ادارے، شراکت داریاں اور پائیدار نظام","موجودہ تعارف","بانی، منتظم، سول سوسائٹی کے کارکن اور علمی شعبے کے پیشہ ور","Academy میں اس کی اہمیت","یہ Find And Study کے ماڈل کے پیچھے موجود ادارہ جاتی سوچ واضح کرتا ہے","تعلیمی پس منظر","انہوں نے 2007 میں سکاریا یونیورسٹی سے پبلک ایڈمنسٹریشن میں بیچلر کی ڈگری مکمل کی۔ 2013 میں انہوں نے مرمرہ یونیورسٹی سے مقامی انتظامیہ اور اختیارات کی غیر مرکزیت میں مقالے پر مبنی ماسٹرز پروگرام کامیابی سے مکمل کیا۔ 2023 میں انہوں نے استنبول یونیورسٹی سے پبلک ایڈمنسٹریشن اور سیاسیات میں پی ایچ ڈی مکمل کی۔","پیشہ ورانہ زندگی کا آغاز","انہوں نے 2006 میں Murat Educational Institutions میں استاد کی حیثیت سے پیشہ ورانہ زندگی شروع کی اور 2018 تک اسی کردار میں کام کرتے رہے۔ اسی عرصے میں انہوں نے تدریسی عمل کو تنظیمی ذمہ داری اور قیادت سے جوڑنے والا پیشہ ورانہ تعارف تشکیل دیا۔","علمی پیشہ ورانہ سفر","2013 میں انہوں نے Istanbul Ayvansaray یونیورسٹی میں لیکچرار کے طور پر کام شروع کیا اور اگست 2019 تک وہاں رہے۔ اس کردار نے اعلیٰ تعلیم، علمی انتظامیہ اور ادارہ جاتی ثقافت سے ان کا تعلق مضبوط کیا۔","سول سوسائٹی اور عوامی کردار","2016 سے 2019 تک Beyoğlu Businessmen Group (BIG) کے سیکریٹری جنرل رہے۔","10 اکتوبر 2017 کو بی اوغلو سٹی کونسل کے ایگزیکٹو بورڈ کے سیکریٹری جنرل منتخب ہوئے اور 2019 کے مقامی انتخابات کے بعد یہ عہدہ چھوڑ دیا۔","2019 میں شروع ہونے والی Akademi Beyoğlu کے بانی ڈائریکٹر رہے۔","21 مئی 2018 کے عمومی اجلاس میں Medeniyet Derneği کے بورڈ کے رکن منتخب ہوئے۔","وہ ریسرچ، یکجہتی اور تعلیم فاؤنڈیشن (ARDEV) کے ڈائریکٹر کے طور پر بھی خدمات انجام دے رہے ہیں۔","Find And Study","وہ Find And Study کے بانی ہیں، جو ترکیہ کی جامعات کو بیرون ملک متعارف کراتی اور بین الاقوامی طلبہ کو ترکیہ کے اعلیٰ تعلیمی اداروں میں داخلے کے لیے معاونت فراہم کرتی ہے۔ یہ کردار تعلیمی فروغ، بین الاقوامی وسعت اور منظم تعاون پر مبنی مشن کی عکاسی کرتا ہے۔","MÜMDER میں کردار","جون 2021 کے عمومی اجلاس میں وہ MÜMDER، یعنی مرمرہ یونیورسٹی کے فارغ التحصیل افراد اور اراکین کی انجمن، کے بورڈ کے رکن اور سول سوسائٹی کی تنظیموں سے تعلقات کے شعبے کے سربراہ منتخب ہوئے۔ یہ ذمہ داری سابق طلبہ سے تعلقات اور سول سوسائٹی کے نیٹ ورکس میں ان کے فعال کردار کو نمایاں کرتی ہے۔","پیشہ ورانہ خلاصہ","Dr. Eymen NAMAZCI نے تعلیم، علمی شعبے، سول سوسائٹی اور ادارہ جاتی قیادت میں اپنا پیشہ ورانہ سفر بنایا ہے۔ ان کا تعارف کاروباری اقدام کو تعلیمی ترقی، عوامی شمولیت اور تنظیمی ڈھانچے کے لیے طویل مدتی وابستگی کے ساتھ یکجا کرتا ہے۔"],"bn":["প্রতিষ্ঠাতা সম্পর্কে: Dr. Eymen NAMAZCI","প্রতিষ্ঠাতা, তাঁর পেশাগত পটভূমি, দৃষ্টিভঙ্গি এবং প্রতিষ্ঠানের বিশ্বাসযোগ্যতার সংক্ষিপ্ত পরিচিতি।","Dr. Eymen NAMAZCI সম্পর্কে","G1 — প্রতিষ্ঠাতা","এই পাঠে Find And Study-এর প্রতিষ্ঠাতা, তাঁর শিক্ষাগত ও পেশাগত পটভূমি এবং শিক্ষা, নাগরিক সমাজ ও কার্যক্রমের উন্নয়নকে একত্র করা প্রতিষ্ঠান গড়ার দৃষ্টিভঙ্গি তুলে ধরা হয়েছে।","প্রতিষ্ঠাতা ও প্রধান নির্বাহী কর্মকর্তা","আন্তর্জাতিক শিক্ষা","নাগরিক সমাজ ও জনবিষয়ক কার্যক্রম","শিক্ষা ও প্রাতিষ্ঠানিক নেতৃত্ব","প্রতিষ্ঠাতার পরিচিতি","Dr. Eymen NAMAZCI হলেন Find And Study-এর প্রতিষ্ঠাতা। প্রতিষ্ঠানটি বিদেশে তুর্কিয়ের বিশ্ববিদ্যালয়গুলোকে তুলে ধরে এবং আন্তর্জাতিক শিক্ষার্থীদের তুর্কিয়েতে পড়াশোনার সুযোগ সম্পর্কে দিকনির্দেশনা দেয়। তিনি শিক্ষা, প্রাতিষ্ঠানিক সমন্বয় ও দীর্ঘমেয়াদি অংশীদারত্ব গড়ে তোলাকে একটি পেশাদার কাঠামোয় একত্র করার জন্য পরিচিত।","জন্ম","ইস্তাম্বুলে জন্মগ্রহণ করেছেন","নেতৃত্বের প্রধান ক্ষেত্র","শিক্ষা, প্রতিষ্ঠান, অংশীদারত্ব ও টেকসই ব্যবস্থা","বর্তমান পরিচিতি","প্রতিষ্ঠাতা, নির্বাহী, নাগরিক সমাজকর্মী ও শিক্ষাজগতের পেশাজীবী","Academy-তে এর গুরুত্ব","এটি Find And Study মডেলের পেছনের প্রাতিষ্ঠানিক চিন্তাধারা ব্যাখ্যা করে","শিক্ষাগত পটভূমি","তিনি ২০০৭ সালে সাকারিয়া বিশ্ববিদ্যালয় থেকে লোকপ্রশাসনে স্নাতক ডিগ্রি অর্জন করেন। ২০১৩ সালে মারমারা বিশ্ববিদ্যালয় থেকে স্থানীয় প্রশাসন ও বিকেন্দ্রীকরণ বিষয়ে গবেষণাপত্রভিত্তিক স্নাতকোত্তর প্রোগ্রাম সফলভাবে সম্পন্ন করেন। ২০২৩ সালে ইস্তাম্বুল বিশ্ববিদ্যালয় থেকে লোকপ্রশাসন ও রাষ্ট্রবিজ্ঞানে পিএইচডি সম্পন্ন করেন।","পেশাগত জীবনের শুরু","তিনি ২০০৬ সালে Murat Educational Institutions-এ শিক্ষক হিসেবে পেশাগত জীবন শুরু করেন এবং ২০১৮ সাল পর্যন্ত এই দায়িত্বে ছিলেন। একই সময়ে তিনি শিক্ষাদানের অভিজ্ঞতার সঙ্গে সাংগঠনিক দায়িত্ব ও নেতৃত্বকে যুক্ত করে নিজের পেশাগত পরিচিতি গড়ে তোলেন।","শিক্ষাজগতের কর্মজীবন","২০১৩ সালে তিনি Istanbul Ayvansaray বিশ্ববিদ্যালয়ে প্রভাষক হিসেবে কাজ শুরু করেন এবং ২০১৯ সালের আগস্ট পর্যন্ত সেখানে কর্মরত ছিলেন। এই ভূমিকা উচ্চশিক্ষা, শিক্ষা প্রশাসন ও প্রাতিষ্ঠানিক সংস্কৃতির সঙ্গে তাঁর সম্পর্ককে আরও দৃঢ় করে।","নাগরিক সমাজ ও জনসম্পৃক্ত দায়িত্ব","২০১৬ থেকে ২০১৯ সাল পর্যন্ত Beyoğlu Businessmen Group (BIG)-এর মহাসচিব হিসেবে দায়িত্ব পালন করেন।","২০১৭ সালের ১০ অক্টোবর বেয়োগলু সিটি কাউন্সিলের নির্বাহী বোর্ডের মহাসচিব নির্বাচিত হন এবং ২০১৯ সালের স্থানীয় নির্বাচনের পর সেই দায়িত্ব ছেড়ে দেন।","২০১৯ সালে চালু হওয়া Akademi Beyoğlu-এর প্রতিষ্ঠাতা পরিচালক হিসেবে দায়িত্ব পালন করেন।","২০১৮ সালের ২১ মে অনুষ্ঠিত সাধারণ সভায় Medeniyet Derneği-এর পরিচালনা পর্ষদের সদস্য নির্বাচিত হন।","তিনি গবেষণা, সংহতি ও শিক্ষা ফাউন্ডেশন (ARDEV)-এর পরিচালক হিসেবেও দায়িত্ব পালন করছেন।","Find And Study","তিনি Find And Study-এর প্রতিষ্ঠাতা। প্রতিষ্ঠানটি বিদেশে তুর্কিয়ের বিশ্ববিদ্যালয়গুলোকে প্রচার করে এবং আন্তর্জাতিক শিক্ষার্থীদের তুর্কি উচ্চশিক্ষায় ভর্তিতে সহায়তা করে। এই ভূমিকা শিক্ষা প্রসার, আন্তর্জাতিকীকরণ ও সুসংগঠিত সহযোগিতার ওপর প্রতিষ্ঠিত লক্ষ্যকে তুলে ধরে।","MÜMDER-এ ভূমিকা","২০২১ সালের জুনের সাধারণ সভায় তিনি MÜMDER, অর্থাৎ মারমারা বিশ্ববিদ্যালয়ের স্নাতক ও সদস্যদের সমিতির পরিচালনা পর্ষদের সদস্য এবং নাগরিক সমাজের সংগঠনগুলোর সঙ্গে সম্পর্ক বিষয়ক ইউনিটের প্রধান নির্বাচিত হন। এই দায়িত্ব প্রাক্তন শিক্ষার্থীদের সঙ্গে সম্পর্ক ও নাগরিক সমাজের নেটওয়ার্কে তাঁর সক্রিয় ভূমিকা তুলে ধরে।","পেশাগত সারসংক্ষেপ","Dr. Eymen NAMAZCI শিক্ষা, শিক্ষাজগৎ, নাগরিক সমাজ ও প্রাতিষ্ঠানিক নেতৃত্বে নিজের কর্মজীবন গড়ে তুলেছেন। তাঁর পরিচিতিতে উদ্যোক্তা উদ্যোগের সঙ্গে শিক্ষা উন্নয়ন, জনসম্পৃক্ততা ও সাংগঠনিক কাঠামোর প্রতি দীর্ঘমেয়াদি অঙ্গীকার যুক্ত হয়েছে।"],"ne":["संस्थापकबारे: Dr. Eymen NAMAZCI","संस्थापक, उहाँको व्यावसायिक पृष्ठभूमि, दृष्टिकोण र संस्थागत विश्वसनीयताको छोटो परिचय।","Dr. Eymen NAMAZCI बारे","G1 — संस्थापक","यस पाठले Find And Study का संस्थापक, उहाँको शैक्षिक तथा व्यावसायिक पृष्ठभूमि र शिक्षा, नागरिक समाज तथा कार्य सञ्चालनको विकासलाई जोड्ने संस्था निर्माणको दृष्टिकोण परिचय गराउँछ।","संस्थापक तथा प्रमुख कार्यकारी अधिकृत","अन्तर्राष्ट्रिय शिक्षा","नागरिक समाज तथा सार्वजनिक मामिला","शैक्षिक तथा संस्थागत नेतृत्व","संस्थापकको परिचय","Dr. Eymen NAMAZCI Find And Study का संस्थापक हुनुहुन्छ। यस संस्थाले तुर्कियेका विश्वविद्यालयहरूलाई विदेशमा प्रवर्द्धन गर्छ र अन्तर्राष्ट्रिय विद्यार्थीहरूलाई तुर्कियेमा अध्ययनका अवसरतर्फ मार्गदर्शन दिन्छ। उहाँ शिक्षा, संस्थागत समन्वय र दीर्घकालीन साझेदारी निर्माणलाई व्यावसायिक संरचनामा जोड्नका लागि परिचित हुनुहुन्छ।","जन्म","इस्तानबुलमा जन्मनुभएको","नेतृत्वका मुख्य क्षेत्र","शिक्षा, संस्था, साझेदारी र दिगो प्रणालीहरू","हालको परिचय","संस्थापक, कार्यकारी, नागरिक समाजका सक्रिय व्यक्ति र शैक्षिक पेशाकर्मी","Academy मा यसको महत्त्व","यसले Find And Study मोडेलपछाडिको संस्थागत सोच स्पष्ट पार्छ","शैक्षिक पृष्ठभूमि","उहाँले सन् २००७ मा सकार्या विश्वविद्यालयबाट सार्वजनिक प्रशासनमा स्नातक पूरा गर्नुभयो। सन् २०१३ मा मारमारा विश्वविद्यालयबाट स्थानीय प्रशासन र विकेन्द्रीकरणमा शोधप्रबन्धसहितको स्नातकोत्तर कार्यक्रम सफलतापूर्वक पूरा गर्नुभयो। सन् २०२३ मा इस्तानबुल विश्वविद्यालयबाट सार्वजनिक प्रशासन र राजनीतिशास्त्रमा पीएचडी पूरा गर्नुभयो।","व्यावसायिक जीवनको सुरुवात","उहाँले सन् २००६ मा Murat Educational Institutions मा शिक्षकका रूपमा व्यावसायिक जीवन सुरु गर्नुभयो र सन् २०१८ सम्म सोही भूमिकामा रहनुभयो। सोही अवधिमा उहाँले शिक्षण अभ्यासलाई संगठनात्मक जिम्मेवारी र नेतृत्वसँग जोड्ने व्यावसायिक परिचय विकास गर्नुभयो।","शैक्षिक कार्यजीवन","सन् २०१३ मा उहाँले Istanbul Ayvansaray विश्वविद्यालयमा व्याख्याताका रूपमा काम सुरु गर्नुभयो र अगस्ट २०१९ सम्म त्यहाँ रहनुभयो। यस भूमिकाले उच्च शिक्षा, शैक्षिक प्रशासन र संस्थागत संस्कृतिसँग उहाँको सम्बन्ध बलियो बनायो।","नागरिक समाज तथा सार्वजनिक भूमिकाहरू","सन् २०१६ देखि २०१९ सम्म Beyoğlu Businessmen Group (BIG) को महासचिवका रूपमा काम गर्नुभयो।","१० अक्टोबर २०१७ मा बेयोग्लु नगर परिषद्को कार्यकारी बोर्डको महासचिवमा निर्वाचित हुनुभयो र सन् २०१९ को स्थानीय निर्वाचनपछि सो भूमिका छोड्नुभयो।","सन् २०१९ मा सुरु भएको Akademi Beyoğlu को संस्थापक निर्देशकका रूपमा काम गर्नुभयो।","२१ मे २०१८ को साधारणसभामा Medeniyet Derneği को सञ्चालक समितिको सदस्यमा निर्वाचित हुनुभयो।","उहाँ अनुसन्धान, ऐक्यबद्धता र शिक्षा प्रतिष्ठान (ARDEV) को निर्देशकका रूपमा पनि कार्यरत हुनुहुन्छ।","Find And Study","उहाँ Find And Study का संस्थापक हुनुहुन्छ। यसले तुर्कियेका विश्वविद्यालयहरूलाई विदेशमा प्रवर्द्धन गर्छ र अन्तर्राष्ट्रिय विद्यार्थीहरूलाई टर्किस उच्च शिक्षामा भर्ना हुन सहयोग गर्छ। यस भूमिकाले शिक्षा प्रवर्द्धन, अन्तर्राष्ट्रियकरण र व्यवस्थित सहकार्यमा आधारित उद्देश्य प्रतिबिम्बित गर्छ।","MÜMDER मा भूमिका","जुन २०२१ को साधारणसभामा उहाँ MÜMDER, अर्थात् मारमारा विश्वविद्यालयका स्नातक तथा सदस्यहरूको संघ, को सञ्चालक समिति सदस्य र नागरिक समाज संस्थाहरूसँग सम्बन्ध विभागको प्रमुखमा निर्वाचित हुनुभयो। यस जिम्मेवारीले पूर्वविद्यार्थी सम्बन्ध र नागरिक समाजको सञ्जालमा उहाँको सक्रिय भूमिका देखाउँछ।","व्यावसायिक सारांश","Dr. Eymen NAMAZCI ले शिक्षा, प्राज्ञिक क्षेत्र, नागरिक समाज र संस्थागत नेतृत्वमा आफ्नो कार्यजीवन निर्माण गर्नुभएको छ। उहाँको परिचयले उद्यमशील पहललाई शैक्षिक विकास, सार्वजनिक सहभागिता र संगठनात्मक संरचनाप्रतिको दीर्घकालीन प्रतिबद्धतासँग जोड्छ।"],"kk":["Құрылтайшы туралы: Dr. Eymen NAMAZCI","Құрылтайшы, оның кәсіби тәжірибесі, көзқарасы және ұйымның сенімділігі туралы қысқаша таныстырылым.","Dr. Eymen NAMAZCI туралы","G1 — Құрылтайшы","Бұл сабақ Find And Study құрылтайшысын, оның академиялық және кәсіби жолын, сондай-ақ білім беруді, азаматтық қоғамды және операциялық дамуды біріктіретін ұйым құру көзқарасын таныстырады.","Құрылтайшы және бас атқарушы директор","Халықаралық білім беру","Азаматтық қоғам және қоғамдық істер","Академиялық және институционалдық көшбасшылық","Құрылтайшының профилі","Dr. Eymen NAMAZCI — Түркия университеттерін шетелде таныстырып, халықаралық студенттерге Түркиядағы оқу мүмкіндіктерін табуға бағыт беретін Find And Study ұйымының құрылтайшысы. Ол білім беруді, ұйымдар арасындағы үйлестіруді және ұзақ мерзімді серіктестік құруды кәсіби құрылымда біріктіруімен танымал.","Туған жері","Ыстанбұлда туған","Көшбасшылық бағыттары","Білім беру, ұйымдар, серіктестіктер және тұрақты жүйелер","Қазіргі профилі","Құрылтайшы, басшы, азаматтық қоғам өкілі және академиялық маман","Academy үшін маңызы","Find And Study моделінің негізіндегі институционалдық ойлауды түсіндіреді","Білімі","2007 жылы Сакария университетінде мемлекеттік басқару мамандығы бойынша бакалавр дәрежесін алды. 2013 жылы Мармара университетінде жергілікті басқару және орталықсыздандыру бойынша диссертациялық магистрлік бағдарламаны сәтті аяқтады. 2023 жылы Ыстанбұл университетінде мемлекеттік басқару және саяси ғылымдар бойынша докторлық оқуын аяқтады.","Кәсіби жолының басталуы","Кәсіби қызметін 2006 жылы Murat Educational Institutions мекемесінде мұғалім болып бастап, осы қызметте 2018 жылға дейін жұмыс істеді. Сол кезеңде ол білім беру тәжірибесін ұйымдық жауапкершілікпен және басшылықпен біріктіретін кәсіби бағыт қалыптастырды.","Академиялық қызметі","2013 жылы Istanbul Ayvansaray университетінде оқытушы болып жұмыс істей бастады және 2019 жылғы тамызға дейін сол жерде қызмет етті. Бұл қызмет оның жоғары біліммен, академиялық басқарумен және ұйым мәдениетімен байланысын нығайтты.","Азаматтық қоғам және қоғамдық қызметтер","2016–2019 жылдары Beyoğlu Businessmen Group (BIG) бас хатшысы болып қызмет етті.","2017 жылғы 10 қазанда Бейоғлу қалалық кеңесінің атқарушы алқасының бас хатшысы болып сайланып, 2019 жылғы жергілікті сайлаудан кейін бұл қызметтен кетті.","2019 жылы ашылған Akademi Beyoğlu ұйымының құрылтайшы директоры болды.","2018 жылғы 21 мамырдағы жалпы жиналыста Medeniyet Derneği басқарма мүшесі болып сайланды.","Сондай-ақ Зерттеу, ынтымақтастық және білім беру қорының (ARDEV) директоры қызметін атқарады.","Find And Study","Ол Түркия университеттерін шетелде таныстыратын және халықаралық студенттердің Түркияның жоғары білім жүйесіне орналасуына қолдау көрсететін Find And Study ұйымының құрылтайшысы. Бұл қызмет білім беруді ілгерілетуге, интернационалдандыруға және жүйелі ынтымақтастыққа негізделген миссияны білдіреді.","MÜMDER ұйымындағы қызметі","2021 жылғы маусымдағы жалпы жиналыста ол MÜMDER — Мармара университеті түлектері мен мүшелерінің қауымдастығы — басқарма мүшесі және азаматтық қоғам ұйымдарымен байланыс бөлімінің басшысы болып сайланды. Бұл жауапкершілік оның түлектермен байланыс пен азаматтық қоғам желілеріндегі белсенді рөлін көрсетеді.","Кәсіби қорытынды","Dr. Eymen NAMAZCI кәсіби жолын білім беру, академиялық орта, азаматтық қоғам және институционалдық басшылық салаларында қалыптастырды. Оның профилі кәсіпкерлік бастаманы білім беруді дамытуға, қоғамдық қатысуға және ұйымдық құрылымға ұзақ мерзімді адалдықпен біріктіреді."],"ky":["Негиздөөчү жөнүндө: Dr. Eymen NAMAZCI","Негиздөөчү, анын кесиптик тажрыйбасы, көз карашы жана уюмдун ишенимдүүлүгү тууралуу кыскача маалымат.","Dr. Eymen NAMAZCI жөнүндө","G1 — Негиздөөчү","Бул сабак Find And Study'дин негиздөөчүсү, анын академиялык жана кесиптик жолу, ошондой эле билим берүүнү, жарандык коомду жана ишмердикти өнүктүрүүнү бириктирген уюм куруу көз карашы менен тааныштырат.","Негиздөөчү жана башкы аткаруучу директор","Эл аралык билим берүү","Жарандык коом жана коомдук иштер","Академиялык жана институционалдык жетекчилик","Негиздөөчүнүн профили","Dr. Eymen NAMAZCI — Түркиянын университеттерин чет өлкөлөрдө тааныштырып, эл аралык студенттерге Түркиядагы окуу мүмкүнчүлүктөрүн табууга багыт берген Find And Study уюмунун негиздөөчүсү. Ал билим берүүнү, мекемелер аралык координацияны жана узак мөөнөттүү өнөктөштүктү кесиптик түзүмдө бириктиргени менен белгилүү.","Туулган жери","Стамбулда туулган","Жетекчиликтин негизги багыттары","Билим берүү, мекемелер, өнөктөштүк жана туруктуу системалар","Учурдагы профили","Негиздөөчү, жетекчи, жарандык коом өкүлү жана академиялык адис","Academy үчүн мааниси","Find And Study моделинин артындагы институттук ой жүгүртүүнү түшүндүрөт","Билими","2007-жылы Сакария университетинде мамлекеттик башкаруу боюнча бакалавр даражасын алган. 2013-жылы Мармара университетинде жергиликтүү башкаруу жана борбордон ажыратуу боюнча диссертациялык магистрдик программаны ийгиликтүү аяктаган. 2023-жылы Стамбул университетинде мамлекеттик башкаруу жана саясий илимдер боюнча докторантураны аяктаган.","Кесиптик жолунун башталышы","Кесиптик ишмердигин 2006-жылы Murat Educational Institutions мекемесинде мугалим болуп баштап, бул кызматта 2018-жылга чейин иштеген. Ошол мезгилде ал билим берүү тажрыйбасын уюштуруучулук жоопкерчилик жана жетекчилик менен айкалыштырган кесиптик багытын өнүктүргөн.","Академиялык ишмердиги","2013-жылы Istanbul Ayvansaray университетинде окутуучу болуп иштей баштап, 2019-жылдын августуна чейин ошол жерде калган. Бул кызмат анын жогорку билим берүү, академиялык башкаруу жана мекеме маданияты менен байланышын бекемдеген.","Жарандык коом жана коомдук кызматтар","2016–2019-жылдары Beyoğlu Businessmen Group (BIG) уюмунун башкы катчысы болгон.","2017-жылдын 10-октябрында Бейоглу шаардык кеңешинин аткаруу кеңешинин башкы катчысы болуп шайланган жана 2019-жылдагы жергиликтүү шайлоодон кийин бул кызматтан кеткен.","2019-жылы ачылган Akademi Beyoğlu уюмунун негиздөөчү директору болгон.","2018-жылдын 21-майындагы жалпы жыйында Medeniyet Derneği башкармалыгынын мүчөсү болуп шайланган.","Ошондой эле Изилдөө, тилектештик жана билим берүү фондунун (ARDEV) директору болуп иштеп келет.","Find And Study","Ал Түркиянын университеттерин чет өлкөлөрдө тааныштырган жана эл аралык студенттердин Түркиянын жогорку билим берүү системасына кабыл алынышын колдогон Find And Study уюмунун негиздөөчүсү. Бул кызмат билим берүүнү жайылтууга, эл аралык өнүгүүгө жана уюшкан кызматташтыкка негизделген миссияны чагылдырат.","MÜMDER уюмундагы кызматы","2021-жылдын июнундагы жалпы жыйында ал MÜMDER — Мармара университетинин бүтүрүүчүлөрү жана мүчөлөрүнүн ассоциациясы — башкармалыгынын мүчөсү жана жарандык коом уюмдары менен байланыш бөлүмүнүн башчысы болуп шайланган. Бул жоопкерчилик анын бүтүрүүчүлөр менен байланышта жана жарандык коом тармактарында активдүү ролун көрсөтөт.","Кесиптик жыйынтык","Dr. Eymen NAMAZCI өзүнүн кесиптик жолун билим берүүдө, академиялык чөйрөдө, жарандык коомдо жана институттук жетекчиликте түзгөн. Анын профили ишкердик демилгени билим берүүнү өнүктүрүүгө, коомдук катышууга жана уюштуруучулук түзүмгө узак мөөнөттүү берилгендик менен айкалыштырат."],"ko":["설립자 소개: Dr. Eymen NAMAZCI","설립자의 전문 경력, 비전, 기관의 신뢰성을 간략히 소개합니다.","Dr. Eymen NAMAZCI 소개","G1 — 설립자","이 강의는 Find And Study 설립자의 학문적·전문적 배경과 교육, 시민사회, 운영 발전을 결합하는 기관 설립 비전을 소개합니다.","설립자 및 최고경영자","국제 교육","시민사회 및 공공 업무","학문 및 기관 리더십","설립자 프로필","Dr. Eymen NAMAZCI는 튀르키예 대학을 해외에 홍보하고 국제 학생에게 튀르키예의 학업 기회를 안내하는 Find And Study의 설립자입니다. 그는 전문적인 조직 구조 안에서 교육, 기관 간 조율, 장기적인 파트너십 구축을 결합하는 것으로 알려져 있습니다.","출생","이스탄불 출생","리더십 중점 분야","교육, 기관, 파트너십, 지속 가능한 시스템","현재 프로필","설립자, 경영자, 시민사회 활동가, 학술 전문가","Academy에서 중요한 이유","Find And Study 모델의 바탕이 되는 기관 운영 철학을 설명합니다","학력","2007년 사카리아 대학교에서 행정학 학사 학위를 취득했습니다. 2013년 마르마라 대학교에서 지방행정 및 분권화 분야의 논문형 석사 과정을 성공적으로 마쳤습니다. 2023년에는 이스탄불 대학교에서 행정학 및 정치학 박사 과정을 마쳤습니다.","초기 전문 경력","2006년 Murat Educational Institutions에서 교사로 전문 경력을 시작하여 2018년까지 해당 역할을 수행했습니다. 같은 기간 교육 실무를 조직 운영 책임 및 리더십과 결합하는 경력을 발전시켰습니다.","학술 경력","2013년 이스탄불 아이반사라이 대학교에서 강사로 일하기 시작하여 2019년 8월까지 재직했습니다. 이 역할을 통해 고등교육, 대학 행정, 기관 문화와의 연결을 강화했습니다.","시민사회 및 공공 분야 역할","2016년부터 2019년까지 Beyoğlu Businessmen Group(BIG)의 사무총장을 역임했습니다.","2017년 10월 10일 베이올루 시의회 집행위원회의 사무총장으로 선출되었으며, 2019년 지방선거 이후 해당 직책을 떠났습니다.","2019년 출범한 Akademi Beyoğlu의 설립 이사를 역임했습니다.","2018년 5월 21일 총회에서 Medeniyet Derneği의 이사회 구성원으로 선출되었습니다.","연구·연대·교육 재단(ARDEV)의 이사로도 활동하고 있습니다.","Find And Study","그는 튀르키예 대학을 해외에 홍보하고 국제 학생의 튀르키예 고등교육기관 진학을 지원하는 Find And Study의 설립자입니다. 이 역할은 교육 홍보, 국제화, 체계적인 협력을 중심으로 한 사명을 반영합니다.","MÜMDER에서의 역할","2021년 6월 총회에서 마르마라 대학교 졸업생 및 구성원 협회인 MÜMDER의 이사회 구성원과 시민사회단체 관계 부문 책임자로 선출되었습니다. 이 책임은 동문 관계와 시민사회 네트워크에서 그가 수행하는 적극적인 역할을 보여 줍니다.","전문 경력 요약","Dr. Eymen NAMAZCI는 교육, 학계, 시민사회, 기관 리더십 전반에 걸쳐 경력을 쌓았습니다. 그의 이력은 기업가적 주도성과 함께 교육 발전, 공공 참여, 조직 체계에 대한 장기적인 헌신을 보여 줍니다."]}};
const hash = text => createHash('sha256').update(text || '').digest('hex');
const escapeHtml = text => text.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
async function main() {
  const apply = process.argv.includes('--apply');
  const status = process.argv.includes('--publish') ? 'published' : 'draft';
  const client = new Client({ connectionString: process.env.DATABASE_URL });
  await client.connect();
  try {
    await client.query('BEGIN ISOLATION LEVEL SERIALIZABLE');
    const result = await client.query('SELECT title, description, content FROM contents WHERE id=$1 FOR SHARE', [bundle.contentId]);
    if (result.rows.length !== 1) throw new Error('Source lesson missing');
    const source = result.rows[0];
    for (const field of Object.keys(bundle.sourceHashes)) {
      if (hash(source[field]) !== bundle.sourceHashes[field]) throw new Error('Source changed: ' + field);
    }
    const existing = await client.query('SELECT language FROM content_translations WHERE content_id=$1', [bundle.contentId]);
    const present = new Set(existing.rows.map(row => row.language));
    const inserted = [];
    const skipped = [];
    for (const [language, strings] of Object.entries(bundle.translations)) {
      if (present.has(language)) { skipped.push(language); continue; }
      if (strings.length !== 37 || strings.some(s => typeof s !== 'string' || !s.trim())) throw new Error('Incomplete language: ' + language);
      const draft = { ...source };
      const chars = Array.from(source.content);
      for (const ref of bundle.references.filter(r => r.field !== 'content')) draft[ref.field] = strings[ref.index];
      for (const ref of bundle.references.filter(r => r.field === 'content').sort((a,b) => b.start-a.start)) {
        chars.splice(ref.start, ref.end-ref.start, escapeHtml(strings[ref.index]));
      }
      draft.content = chars.join('');
      if (apply) {
        const row = await client.query("INSERT INTO content_translations (content_id,language,title,description,content,status) VALUES ($1,$2,$3,$4,$5,$6) RETURNING id", [bundle.contentId, language, draft.title, draft.description, draft.content, status]);
        inserted.push({ language, id: row.rows[0].id, bodyHash: hash(draft.content) });
      } else inserted.push({ language, bodyHash: hash(draft.content) });
    }
    const report = { status, mode: apply ? 'apply' : 'dry-run', contentId: bundle.contentId, inserted, skipped };
    // Save the exact inserted IDs inside the existing root-only backup directory.
    if (apply) writeFileSync('/var/backups/academy-languages/founder-drafts-' + Date.now() + '.json', JSON.stringify(report, null, 2), { mode: 0o600, flag: 'wx' });
    await client.query(apply ? 'COMMIT' : 'ROLLBACK');
    console.log(JSON.stringify(report, null, 2));
  } catch (error) {
    await client.query('ROLLBACK');
    throw error;
  } finally { await client.end(); }
}
main().catch(error => { console.error(error.message); process.exitCode=1; });
